import { Pin, PinOff } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { MDPreview } from '@/components/ui/md-preview';
import { Spinner } from '@/components/ui/spinner';
import { formatDate } from '@/utils/format';
import { ROLES } from '@/lib/authorization';

import { useDiscussion } from '../api/get-discussion';
import { useToggleDiscussionPin } from '../api/toggle-discussion-pin';
import { UpdateDiscussion } from '../components/update-discussion';
import { useAuthorization } from '@/lib/authorization';

export const DiscussionView = ({ discussionId }: { discussionId: string }) => {
  const discussionQuery = useDiscussion({
    discussionId,
  });
  const { checkAccess, role } = useAuthorization();

  const togglePinMutation = useToggleDiscussionPin();

  const canPin = role === ROLES.ADMIN;

  if (discussionQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const discussion = discussionQuery?.data?.data;

  if (!discussion) return null;

  const isPinned = discussion.isPinned;

  return (
    <div>
      <div className="mb-4 flex items-center justify-between">
        <div>
          <span className="text-xs font-bold">
            {formatDate(discussion.createdAt)}
          </span>
          {discussion.author && (
            <span className="ml-2 text-sm font-bold">
              by {discussion.author.firstName} {discussion.author.lastName}
            </span>
          )}
        </div>
        {isPinned && (
          <span className="inline-flex items-center gap-1 rounded-full bg-amber-100 px-2.5 py-0.5 text-xs font-medium text-amber-800">
            <Pin className="h-3 w-3" />
            Pinned
          </span>
        )}
      </div>
      {canPin && (
        <div className="mb-4 flex justify-end">
          <Button
            variant="outline"
            size="sm"
            onClick={() => togglePinMutation.mutate({ discussionId })}
            isLoading={togglePinMutation.isPending}
            icon={isPinned ? <PinOff className="h-4 w-4" /> : <Pin className="h-4 w-4" />}
          >
            {isPinned ? 'Unpin' : 'Pin'}
          </Button>
        </div>
      )}
      <div className="mt-6 flex flex-col space-y-16">
        <div className="flex justify-end">
          <UpdateDiscussion discussionId={discussionId} />
        </div>
        <div>
          <div className="overflow-hidden bg-white shadow sm:rounded-lg">
            <div className="px-4 py-5 sm:px-6">
              <div className="mt-1 max-w-2xl text-sm text-gray-500">
                <MDPreview value={discussion.body} />
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

